import React, { useState, useRef, useEffect } from 'react';
import { useNavigate, useLocation, Outlet } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';

const NAV = [
  { path: '/dashboard', icon: '◈', label: 'INICIO' },
  { path: '/dashboard/inventario', icon: '⊞', label: 'INVENTARIO' },
  { path: '/dashboard/mantenimiento', icon: '⚙', label: 'MANTENIMIENTO' },
  { path: '/dashboard/reportes', icon: '◉', label: 'REPORTES' },
];

function CircuitBackground() {
  const canvasRef = useRef(null);
  const scrollRef = useRef(0);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    let frame = 0, animId;

    const resize = () => { canvas.width = canvas.offsetWidth; canvas.height = canvas.offsetHeight; };
    resize();
    window.addEventListener('resize', resize);

    const onScroll = (e) => { scrollRef.current += e.deltaY * 0.003; };
    canvas.parentElement.addEventListener('wheel', onScroll, { passive: true });

    // Circuit grid nodes
    const COLS = 18, ROWS = 12;
    const nodes = [];
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        nodes.push({
          x: (c / (COLS-1)) * 100,
          y: (r / (ROWS-1)) * 100,
          active: Math.random() > 0.5,
          pulseOffset: Math.random() * Math.PI * 2,
        });
      }
    }

    // Data flow lines
    const flows = Array.from({ length: 12 }, () => ({
      col: Math.floor(Math.random() * COLS),
      progress: Math.random(),
      speed: 0.002 + Math.random() * 0.004,
      color: Math.random() > 0.5 ? '#f59e0b' : '#fb923c',
    }));

    const draw = () => {
      const w = canvas.width, h = canvas.height;
      ctx.clearRect(0, 0, w, h);
      frame += 0.01;
      const scroll = scrollRef.current;

      // Grid lines
      ctx.strokeStyle = 'rgba(245,158,11,0.04)';
      ctx.lineWidth = 1;
      const cellW = w / (COLS-1), cellH = h / (ROWS-1);

      // Horizontal lines
      for (let r = 0; r < ROWS; r++) {
        const y = r * cellH;
        ctx.beginPath();
        ctx.moveTo(0, y); ctx.lineTo(w, y);
        ctx.stroke();
      }
      // Vertical lines
      for (let c = 0; c < COLS; c++) {
        const x = c * cellW;
        ctx.beginPath();
        ctx.moveTo(x, 0); ctx.lineTo(x, h);
        ctx.stroke();
      }

      // Highlight some circuit paths
      const activePaths = [
        [0,0, 3,0, 3,2, 6,2, 6,5],
        [12,0, 12,3, 15,3, 15,6, 17,6],
        [0,8, 4,8, 4,11, 8,11],
        [9,0, 9,4, 14,4],
        [0,5, 5,5, 5,9, 10,9, 10,11],
        [17,2, 13,2, 13,7, 17,7],
      ];

      activePaths.forEach((path, pi) => {
        const pulse = (Math.sin(frame * 1.5 + pi * 1.2) + 1) / 2;
        ctx.strokeStyle = `rgba(245,158,11,${0.12 + pulse * 0.1})`;
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        for (let i = 0; i < path.length; i += 2) {
          const x = path[i] * cellW, y = path[i+1] * cellH;
          i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
        }
        ctx.stroke();

        // Corner dots on path
        for (let i = 0; i < path.length; i += 2) {
          const x = path[i] * cellW, y = path[i+1] * cellH;
          ctx.fillStyle = `rgba(251,191,36,${0.3 + pulse * 0.4})`;
          ctx.beginPath(); ctx.arc(x, y, 2.5, 0, Math.PI * 2); ctx.fill();
        }
      });

      // Flowing data pulses along vertical lines (scroll-reactive)
      flows.forEach(fl => {
        fl.progress = (fl.progress + fl.speed + scroll * 0.01) % 1;
        const x = fl.col * cellW;
        const y = fl.progress * h;
        const g = ctx.createLinearGradient(x, y-20, x, y+20);
        g.addColorStop(0, fl.color + '00');
        g.addColorStop(0.5, fl.color + 'cc');
        g.addColorStop(1, fl.color + '00');
        ctx.strokeStyle = g;
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(x, y-20); ctx.lineTo(x, y+20);
        ctx.stroke();
      });

      // Pulsing nodes
      nodes.forEach(n => {
        if (!n.active) return;
        const nx = n.x / 100 * w, ny = n.y / 100 * h;
        const p = (Math.sin(frame * 2 + n.pulseOffset) + 1) / 2;
        ctx.fillStyle = `rgba(245,158,11,${0.15 + p * 0.35})`;
        ctx.beginPath(); ctx.arc(nx, ny, 2 + p, 0, Math.PI * 2); ctx.fill();

        if (p > 0.7) {
          const ring = ctx.createRadialGradient(nx, ny, 0, nx, ny, 10);
          ring.addColorStop(0, 'rgba(245,158,11,0.15)');
          ring.addColorStop(1, 'rgba(245,158,11,0)');
          ctx.fillStyle = ring;
          ctx.beginPath(); ctx.arc(nx, ny, 10, 0, Math.PI * 2); ctx.fill();
        }
      });

      // Reset scroll drift
      scrollRef.current *= 0.9;

      animId = requestAnimationFrame(draw);
    };
    draw();
    return () => { cancelAnimationFrame(animId); window.removeEventListener('resize', resize); };
  }, []);

  return <canvas ref={canvasRef} style={{ position:'absolute', inset:0, width:'100%', height:'100%', opacity:0.7 }} />;
}

export default function DashboardLayout() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const loc = useLocation();
  const [collapsed, setCollapsed] = useState(false);
  const [time, setTime] = useState(new Date());

  useEffect(() => {
    const t = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(t);
  }, []);

  return (
    <div style={S.wrap}>
      {/* Sidebar */}
      <aside style={{ ...S.sidebar, width: collapsed ? 62 : 220, transition: 'width 0.35s cubic-bezier(0.4,0,0.2,1)' }}>
        <div style={S.sideTop}>
          <div style={S.brand} onClick={() => setCollapsed(!collapsed)}>
            <span style={S.brandGear}>⚙</span>
            {!collapsed && (
              <div style={{ overflow:'hidden' }}>
                <div style={S.brandName}>MINING</div>
                <div style={S.brandSub}>CONTROL</div>
              </div>
            )}
          </div>
          {!collapsed && (
            <div style={S.clock}>
              <span style={S.clockText}>{time.toLocaleTimeString('es-BO', { hour12: false })}</span>
              <div style={S.clockDate}>{time.toLocaleDateString('es-BO', { day:'2-digit', month:'short' }).toUpperCase()}</div>
            </div>
          )}
        </div>

        <nav style={S.nav}>
          {NAV.map((item, i) => {
            const active = loc.pathname === item.path || (item.path !== '/dashboard' && loc.pathname.startsWith(item.path));
            return (
              <button key={item.path} onClick={() => navigate(item.path)}
                style={{
                  ...S.navItem,
                  ...(active ? S.navActive : {}),
                  justifyContent: collapsed ? 'center' : 'flex-start',
                  animationDelay: `${i * 0.05}s`,
                }}
                className={`nav-item${active ? ' nav-active' : ''}`}>
                <span style={{ ...S.navIcon, ...(active ? { filter:'drop-shadow(0 0 6px rgba(245,158,11,0.8))' } : {}) }}>
                  {item.icon}
                </span>
                {!collapsed && <span style={S.navLabel}>{item.label}</span>}
                {active && <div style={{ ...S.navGlow, right: collapsed ? '50%' : 8 }} />}
              </button>
            );
          })}
        </nav>

        <div style={S.sideBottom}>
          {!collapsed && (
            <div style={S.userInfo}>
              <div style={S.userAvatar}>{user?.username?.[0]?.toUpperCase()}</div>
              <div style={{ overflow:'hidden' }}>
                <div style={S.userName}>{user?.username}</div>
                <div style={S.userRole}>{user?.role?.toUpperCase()}</div>
              </div>
            </div>
          )}
          <button onClick={logout} style={{ ...S.logoutBtn, justifyContent: collapsed ? 'center' : 'flex-start' }} className="logout-btn">
            <span style={{ fontSize:16 }}>⏻</span>
            {!collapsed && <span>SALIR</span>}
          </button>
        </div>
      </aside>

      {/* Main */}
      <main style={S.main}>
        <header style={S.topbar}>
          <div style={S.topLeft}>
            <div style={S.systemDot} />
            <span style={S.topText}>SISTEMA ACTIVO</span>
            <span style={S.topDivider}>◆</span>
            <span style={S.topText}>{time.toLocaleDateString('es-BO', { weekday:'long', year:'numeric', month:'long', day:'numeric' })}</span>
          </div>
          <div style={S.topRight}>
            <div style={S.versionBadge}>v2.0.1</div>
          </div>
        </header>

        <div style={{ ...S.content, position:'relative', overflow:'auto' }}>
          <CircuitBackground />
          <div style={{ position:'relative', zIndex:1 }}>
            <Outlet />
          </div>
        </div>
      </main>

      <style>{`
        @keyframes blink{0%,100%{opacity:1}50%{opacity:0.3}}
        @keyframes gearSpin{to{transform:rotate(360deg)}}
        @keyframes navIn{from{opacity:0;transform:translateX(-14px)}to{opacity:1;transform:translateX(0)}}
        @keyframes scrollFlow{
          0%{background-position:0% 0%}
          100%{background-position:0% 100%}
        }
        .nav-item{animation:navIn 0.4s ease forwards;}
        .nav-item:hover:not(.nav-active){background:rgba(245,158,11,0.06)!important;color:#d97706!important;}
        .logout-btn:hover{background:rgba(239,68,68,0.1)!important;border-color:rgba(239,68,68,0.5)!important;}
      `}</style>
    </div>
  );
}

