import React, { useState, useEffect } from 'react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';
import API from '../api';

const COLORS = ['#f59e0b', '#fb923c', '#fbbf24', '#f97316'];

export default function Reportes() {
  const [stats, setStats] = useState(null);
  const [equipment, setEquipment] = useState([]);

  useEffect(() => {
    API.get('/stats').then(r => setStats(r.data)).catch(() => {});
    API.get('/equipment').then(r => setEquipment(r.data)).catch(() => {});
  }, []);

  const barData = (stats?.by_area || []).map(a => ({
    name: a.area.slice(0, 5), total: a.count,
    op: equipment.filter(e => e.area === a.area && e.status === 'operational').length,
  }));

  const pieData = [
    { name: 'Operativo', value: stats?.operational || 0 },
    { name: 'Mantenimiento', value: stats?.maintenance || 0 },
    { name: 'Crítico', value: stats?.critical || 0 },
  ].filter(d => d.value > 0);

  return (
    <div style={s.wrap}>
      <div style={s.header}>
        <h1 style={s.title}>REPORTES Y ANÁLISIS</h1>
        <p style={s.subtitle}>Vista estadística del sistema</p>
      </div>

      <div style={s.grid}>
        <div style={s.card}>
          <div style={s.cardTitle}>EQUIPOS POR ÁREA</div>
          <ResponsiveContainer width="100%" height={220}>
            <BarChart data={barData} barGap={4}>
              <XAxis dataKey="name" tick={{ fill: '#d97706', fontSize: 10, fontFamily: 'Share Tech Mono' }} axisLine={false} tickLine={false} />
              <YAxis tick={{ fill: '#78350f', fontSize: 10 }} axisLine={false} tickLine={false} />
              <Tooltip contentStyle={{ background: '#1a1000', border: '1px solid rgba(245,158,11,0.3)', borderRadius: 8, color: '#f59e0b', fontFamily: 'Share Tech Mono', fontSize: 11 }} />
              <Bar dataKey="total" fill="#00d4ff22" stroke="#00d4ff" strokeWidth={1} radius={[4, 4, 0, 0]} name="Total" />
              <Bar dataKey="op" fill="#00ff8844" stroke="#00ff88" strokeWidth={1} radius={[4, 4, 0, 0]} name="Operativo" />
            </BarChart>
          </ResponsiveContainer>
        </div>

        <div style={s.card}>
          <div style={s.cardTitle}>DISTRIBUCIÓN DE ESTADO</div>
          <ResponsiveContainer width="100%" height={220}>
            <PieChart>
              <Pie data={pieData} cx="50%" cy="50%" innerRadius={60} outerRadius={90} paddingAngle={4} dataKey="value">
                {pieData.map((_, i) => (
                  <Cell key={i} fill={[COLORS[0], COLORS[1], '#ff3366'][i]} stroke="none" />
                ))}
              </Pie>
              <Legend iconType="circle" wrapperStyle={{ fontFamily: 'Share Tech Mono', fontSize: 10, color: '#d97706' }} />
              <Tooltip contentStyle={{ background: '#1a1000', border: '1px solid rgba(245,158,11,0.3)', borderRadius: 8, color: '#f59e0b', fontFamily: 'Share Tech Mono', fontSize: 11 }} />
            </PieChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div style={s.tableCard}>
        <div style={s.cardTitle}>LISTADO COMPLETO</div>
        <table style={s.table}>
          <thead>
            <tr>{['ÁREA', 'N°', 'EQUIPO', 'ESTADO', 'NOTAS'].map(h => <th key={h} style={s.th}>{h}</th>)}</tr>
          </thead>
          <tbody>
            {equipment.map(e => (
              <tr key={e.id} style={s.tr}>
                <td style={{ ...s.td, color: ['#f59e0b','#ffd700','#00ff88','#ff8c00'][['TRITURACION','MOLIENDA','FLOTACION','RECIRCULACION'].indexOf(e.area)] }}>{e.area}</td>
                <td style={{ ...s.td, fontFamily: 'Orbitron', fontSize: 11 }}>{e.number}</td>
                <td style={s.td}>{e.name}</td>
                <td style={s.td}>
                  <span style={{ fontFamily: 'Share Tech Mono', fontSize: 9, color: e.status === 'operational' ? '#00ff88' : '#ffd700', letterSpacing: 1 }}>
                    ● {e.status === 'operational' ? 'OPERATIVO' : 'MANTENIMIENTO'}
                  </span>
                </td>
                <td style={{ ...s.td, color: '#78350f', fontSize: 12 }}>{e.notes || '—'}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

const s = {
  wrap: { display: 'flex', flexDirection: 'column', gap: 20 },
  header: { paddingBottom: 16, borderBottom: '1px solid rgba(245,158,11,0.1)' },
  title: { fontFamily: 'Orbitron', fontSize: 20, fontWeight: 800, color: '#f59e0b', letterSpacing: 4 },
  subtitle: { fontFamily: 'Share Tech Mono', fontSize: 11, color: '#78350f', letterSpacing: 2, marginTop: 4 },
  grid: { display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 },
  card: { background: 'rgba(4,20,36,0.9)', border: '1px solid rgba(245,158,11,0.1)', borderRadius: 12, padding: '18px 20px' },
  cardTitle: { fontFamily: 'Orbitron', fontSize: 10, color: '#d97706', letterSpacing: 3, marginBottom: 16 },
  tableCard: { background: 'rgba(4,20,36,0.9)', border: '1px solid rgba(245,158,11,0.1)', borderRadius: 12, padding: '18px 24px' },
  table: { width: '100%', borderCollapse: 'collapse', marginTop: 8 },
  th: { fontFamily: 'Orbitron', fontSize: 9, color: '#78350f', letterSpacing: 3, padding: '8px 12px', textAlign: 'left', borderBottom: '1px solid rgba(245,158,11,0.1)' },
  tr: { borderBottom: '1px solid rgba(245,158,11,0.05)' },
  td: { fontFamily: 'Rajdhani', fontSize: 13, color: '#fef3c7', padding: '9px 12px' },
};
